EXTRA_ALANIA_RU = ("Районы Алании: от Авсаллара до Каргыджака",
                   "К западу от центра идут Конаклы, Тюрклер, Авсаллар, Инжекум, Окурджалар и Паяллар — более спокойная полоса с соснами, бухтами и низкой плотностью. К востоку через Тосмур и Демирташ к Махмутлару и Каргыджаку застройка становится плотнее и выше, а магазинов и кафе рядом больше. Оба лежит сразу за центром и держит городской быт рядом с морем, Джикджилли удалён от берега и живёт медленнее. Новостройки Алании — это в основном комплексы с бассейном и охраной, вторичное жильё чаще даёт большую площадь и сложившееся окружение. Жильё в Алании выбирают именно по этой разнице, а не по расстоянию до моря в метрах.")


def block(title, sections):
    out = ['    seoTitle: "%s",' % title, "    seoSections: ["]
    for heading, text in sections:
        out.append("      {")
        out.append('        heading: "%s",' % heading)
        out.append('        text: "%s",' % text)
        out.append("      },")
    out.append("    ],")
    return "\n".join(out) + "\n"


def main():
    src = io.open(PAGES, encoding="utf-8").read()
    for slug, (title, sections) in ARTICLES.items():
        pos = src.index('slug: "%s"' % slug)
        end = src.index("\n  },\n", pos)
        assert "seoSections" not in src[pos:end], slug
        src = src[:end + 1] + block(title, sections) + src[end + 1:]

    anchor = 'Вид на жительство — отдельный от собственности вопрос со своими правилами.",\n      },\n    ],'
    assert anchor in src
    src = src.replace(anchor, anchor[:anchor.index("\n    ],")] + "\n      {\n"
                      '        heading: "%s",\n        text: "%s",\n      },\n    ],'
                      % EXTRA_ALANIA_RU)
    io.open(PAGES, "w", encoding="utf-8").write(src)
    print("spliced", len(ARTICLES) + 1)


if __name__ == "__main__":
    main()
